using System;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Drawing;using System.Collections.Generic;using System.Windows.Forms;
namespace GearLab {
 public static class Workspace64Tests {
  static IEnumerable<Control> All(Control c){yield return c;foreach(Control child in c.Controls)foreach(var next in All(child))yield return next;}
  public static int Run(string folder){folder=Path.GetFullPath(folder);Directory.CreateDirectory(folder);Environment.SetEnvironmentVariable("GEARLAB_PROFILE_DIR",Path.Combine(folder,"profile"));int checks=0;var report=new StringBuilder();Action<bool,string> check=(ok,message)=>{if(!ok)throw new Exception(message);checks++;report.AppendLine("PASS "+message);};Action pump=()=>{for(int i=0;i<8;i++){Application.DoEvents();Thread.Sleep(10);}};try{
   AppSettings.Commit(new AppSettings());using(var a=new PlaybackControl())using(var b=new PlaybackControl()){a.SpeedField.Value=2.25m;check(AppSettings.Current.AnimationScale==2.25,"playback speed applies immediately");check(b.SpeedField.Value==2.25m,"speed controls synchronize across workspaces");check(AppSettings.LoadFrom(AppSettings.SettingsPath).AnimationScale==2.25,"speed persists");a.SpeedField.Value=.01m;check(AppSettings.Current.AnimationScale==.01,"minimum playback speed");a.SpeedField.Value=10;check(AppSettings.Current.AnimationScale==10,"maximum playback speed");}
   using(var number=new SafeNumber{Minimum=-100,Maximum=100,DecimalPlaces=2,Width=148}){number.Commit(23.75m);number.CreateControl();var editor=number.Controls.OfType<TextBoxBase>().First();var arrows=number.Controls.Cast<Control>().First(c=>c.GetType().Name=="UpDownButtons");check(!editor.Bounds.IntersectsWith(arrows.Bounds),"stepper text never overlaps buttons");decimal value;check(number.TryRead(out value)&&value==23.75m,"new stepper preserves decimal input");number.Text="oops";check(!number.TryRead(out value),"new stepper rejects invalid input");number.Text="-12,50";check(number.TryRead(out value)&&value==-12.5m,"new stepper accepts signed comma input");number.Commit(-12.5m);number.UpButton();check(number.Value==-11.5m,"new stepper preserves increment behavior");}
   using(var reducers=new ReducerWorkspaceForm())using(var shell=new WorkspaceShell(reducers)){shell.Show();pump();check(reducers.MainView!=null,"reducer workspace starts");var main=reducers.MainView;check(main.CurrentParameters.Ratio==Engine.Starter(0).Ratio&&Engine.Calculate(main.CurrentParameters).Valid,"docking initialization preserves valid starter dimensions");var dock=main.inspectorWorkspace;check(All(dock.ParameterContent).OfType<TrackBar>().All(t=>!t.Visible),"parameter sliders hidden by default");var input=All(dock.ParameterContent).OfType<SafeNumber>().First(n=>n.AccessibleName=="Входной момент, Н·м");input.Text="unfinished";string before=ReleaseSupport.Serialize(main.CurrentParameters);var content=dock.ParameterContent;dock.FloatPanel(new Point(120,100));pump();check(dock.IsFloating&&ReferenceEquals(content,dock.ParameterContent)&&content.FindForm()==dock.FloatingForm,"same editor is reparented into floating window");check(input.Text=="unfinished"&&before==ReleaseSupport.Serialize(main.CurrentParameters),"detach preserves pending input and project parameters");dock.FloatingForm.Size=new Size(520,600);dock.FloatingForm.Location=new Point(200,130);pump();check(content.ClientSize.Width>450,"floating content resizes with window");AppSettings.SetLanguage(GearLanguage.English);pump();check(dock.FloatingForm.Text=="Reducer properties","floating panel language updates immediately");check(All(shell).OfType<ToolStrip>().Any(t=>t.Items.Cast<ToolStripItem>().Any(i=>i.Text=="EN")),"top bar reflects language");check(input.Text=="unfinished","language preserves pending numeric edit");check(AppSettings.LoadFrom(AppSettings.SettingsPath).Language==GearLanguage.English,"language saved without Apply");dock.SetActive(false);check(!dock.FloatingForm.Visible,"floating panel hides with inactive workspace");dock.SetActive(true);check(dock.FloatingForm.Visible,"floating panel returns with workspace");dock.DockPanel("left");pump();check(!dock.IsFloating&&dock.Placement=="left"&&content.Parent.Parent==dock.Split.Panel1,"dock left reparents same editor");dock.Split.SplitterDistance=450;pump();check(content.ClientSize.Width>380,"docked panel width is adjustable");dock.DockPanel("right");pump();check(dock.Placement=="right"&&ReferenceEquals(content,dock.ParameterContent)&&input.Text=="unfinished","dock right preserves controls and edits");input.Text="0.350";input.Commit(.35m);All(main).OfType<Button>().First(x=>x.Text=="Calculate").PerformClick();
    shell.Navigate("settings");pump();var settings=(SettingsForm)shell.Pages.SelectedTab.Tag;var sections=All(settings).OfType<ListBox>().Single();sections.SelectedIndex=3;pump();var languages=All(settings).OfType<ComboBox>().Single();languages.SelectedIndex=0;pump();check(AppSettings.Current.Language==GearLanguage.Русский&&All(settings).OfType<Label>().Any(l=>l.Text=="Язык интерфейса"),"settings selector switches to Russian without Apply");languages.SelectedIndex=1;pump();check(AppSettings.Current.Language==GearLanguage.English&&All(settings).OfType<Label>().Any(l=>l.Text=="Interface language"),"settings selector switches to English without Apply");AppSettings.SetAnimationSpeed(1.75);check(settings.Draft.AnimationScale==1.75&&settings.ApplyDraft()&&AppSettings.Current.AnimationScale==1.75,"applying other preferences preserves speed changed outside settings");shell.Navigate("reducer");dock.FloatPanel(new Point(160,110));pump();dock.FloatingForm.Size=new Size(480,620);dock.FloatingForm.Location=new Point(165,115);pump();dock.FloatingForm.Close();pump();check(!dock.IsFloating&&dock.Placement=="right","floating X returns panel to workspace");dock.FloatPanel(new Point(170,120));pump();dock.FloatingForm.Size=new Size(490,610);dock.FloatingForm.Location=new Point(175,125);pump();main.WorkspaceApproveClose();shell.ApproveTestClose();shell.Close();}
   var saved=InspectorLayout.Load();check(saved.Dock=="floating"&&saved.FloatingWidth==490&&saved.FloatingHeight==610,"layout saves floating position and size");using(var next=new MainForm()){next.Show();pump();check(next.inspectorWorkspace.IsFloating&&next.inspectorWorkspace.FloatingForm.Width==490,"floating layout restores on next launch");next.inspectorWorkspace.DockPanel("right");next.WorkspaceApproveClose();next.Close();}
   File.WriteAllText(Path.Combine(folder,"workspace64-results.txt"),report+"PASS "+checks+" assertions",Encoding.UTF8);return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"workspace64-error.txt"),report+ex.ToString(),Encoding.UTF8);return 1;}}
 }
}
